import streamlit as st
import streamlit.components.v1 as components
# Unpack immutable static resources once at app startup, outside patient timing.
with zipfile.ZipFile(Path(__file__).parent/'deployment_assets.zip') as assets:
    for item in assets.infolist():
        target=Path(__file__).parent/item.filename
        if not target.exists():
            assets.extract(item,Path(__file__).parent)
from jobs import Jobs
