@st.cache_resource
def frontend():
    # Chunked callback transport revision 4.
    folder=Path(tempfile.mkdtemp(prefix="coremap-original-ui-"))
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as z:z.extractall(folder)
    shutil.copyfile(Path(__file__).parent/'templates'/'MNI152_T1_1mm_brain.nii.gz',folder/'mni-reference.nii.gz')
    shutil.copytree(Path(__file__).parent/'display_assets',folder/'display_assets',dirs_exist_ok=True)
    (folder/'bridge.js').write_text(r'''(() => {
 const pending=new Map();let sequence=0;let checked=false;
 document.documentElement.dataset.coremapTransport="initializing";
 const post=(type,extra={})=>parent.postMessage({isStreamlitMessage:true,type,...extra},'*');
 window.addEventListener('message',event=>{
  if(event.source!==parent||event.data?.type!=='streamlit:render')return;
  document.documentElement.dataset.coremapBuild=event.data.args?.build||"unknown";
  console.info("CoreMap render",event.data.args?.build);
  if(!checked){checked=true;setTimeout(()=>sendRequest({url:"/api/health"}).then(r=>r.json()).then(r=>{document.documentElement.dataset.coremapTransport=r.ok?"ready":"error";console.info("CoreMap connection",r.ok);}).catch(e=>{document.documentElement.dataset.coremapTransport="failed";console.error("CoreMap connection",e.message);}),0);}
  const response=event.data.args?.response;
  if(response&&pending.has(response.id)){
   const item=pending.get(response.id);clearInterval(item.retry);clearTimeout(item.timer);pending.delete(response.id);
   item.resolve(new Response(JSON.stringify(response.data),{status:response.code||200,headers:{'Content-Type':'application/json'}}));
  }
 });
 const originalFetch=window.fetch.bind(window);
 const encode=file=>new Promise((resolve,reject)=>{if(file.size>80*1024*1024){reject(Error('Each image must be at most 80 MB.'));return;}const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});
 const sendRequest=async request=>{
  const id=Date.now().toString(36)+'-'+(++sequence);
  const response=new Promise((resolve,reject)=>{const timer=setTimeout(()=>{clearInterval(pending.get(id)?.retry);pending.delete(id);reject(Error('Server response timed out after 60 seconds. / 服务器60秒未响应，尚未确认完成。'));},60000);pending.set(id,{resolve,reject,timer});});
  const send=()=>post('streamlit:setComponentValue',{value:{...request,id,transportAttempt:Date.now()},dataType:'json'});
  pending.get(id).retry=setInterval(send,10000);send();return response;
 };
 window.fetch=async(url,options={})=>{
  if(typeof url!=='string'||!url.startsWith('/api/'))return originalFetch(url,options);
  const files={};
  if(options.body instanceof FormData){for(const [key,file] of options.body)files[key]=await encode(file);}
  else if(options.body instanceof Blob)files.core=await encode(options.body);
  if(Object.values(files).reduce((s,v)=>s+v.length,0)>170*1024*1024)throw Error('Combined upload is too large.');
  const uploadId=Date.now().toString(36)+'-'+(++sequence);
  for(const [name,value] of Object.entries(files)){for(let offset=0;offset<value.length;offset+=131072){const reply=await sendRequest({url:'/api/upload-chunk',uploadId,name,offset,total:value.length,chunk:value.slice(offset,offset+131072)});const ack=await reply.json();if(!reply.ok)throw Error(ack.error);}}
  const reply=await sendRequest({url,side:options.headers?.['X-Lesion-Side'],uploadId:Object.keys(files).length?uploadId:null,files:{}});
  if(url!=='/api/quantify'||!reply.ok)return reply;
  const started=await reply.json();
  for(;;){
   await new Promise(resolve=>setTimeout(resolve,2000));
   const poll=await sendRequest({url:'/api/quantification/'+started.job_id});
   if(!poll.ok)return poll;
   const job=await poll.json();
   if(job.status==='error')return new Response(JSON.stringify({error:job.error}),{status:400});
   if(job.status==='complete')return new Response(JSON.stringify(job.result),{status:200,headers:{'Content-Type':'application/json'}});
  }
 };
 post('streamlit:componentReady',{apiVersion:1});
 window.addEventListener('load',()=>{let height=0;const resize=()=>{const next=Math.max(900,document.documentElement.scrollHeight);if(next!==height){height=next;post('streamlit:setFrameHeight',{height});}};new ResizeObserver(resize).observe(document.body);resize();});
})();''',encoding='utf-8')
    return str(folder)

@st.cache_resource
def service():return Jobs()

def handle(request,manager,owner):
    url=request['url']
    if url=='/api/health':return {'ok':True,'build':BUILD}
    uploads=st.session_state.setdefault('original_uploads',{})
    now=time.time()
    for key in list(uploads):
        if now-uploads[key]['created']>1200:del uploads[key]
    if url=='/api/upload-chunk':
        name=request['name'];offset=int(request['offset']);total=int(request['total']);chunk=request['chunk']
        if name not in ('cbf','core') or not 0<total<=112*1024*1024 or len(chunk)>131072:
            raise ValueError('Invalid upload chunk')
        upload=uploads.setdefault(request['uploadId'],{'created':now,'files':{}})
        item=upload['files'].setdefault(name,{'total':total,'data':''})
        if item['total']!=total or offset!=len(item['data']) or offset+len(chunk)>total:
            raise ValueError('Upload chunk out of sequence')
        item['data']+=chunk
        return {'received':len(item['data'])}
    if request.get('uploadId'):
        upload=uploads.get(request['uploadId'])
        if not upload or any(len(v['data'])!=v['total'] for v in upload['files'].values()):
            raise ValueError('Upload incomplete; no imaging task was started')
        request={**request,'files':{k:v['data'] for k,v in upload['files'].items()}}
    if url in ('/api/register','/api/quantify'):
        files={key:io.BytesIO(base64.b64decode(value,validate=True)) for key,value in request.get('files',{}).items()}
        mode='native' if url=='/api/register' else 'mni'
        # Retries reuse the same worker job; Streamlit may rerun a waiting callback.
        submitted=st.session_state.setdefault('original_submitted_jobs',{})
        job_id=submitted.get(request['id'])
        if job_id is None:
            job_id=manager.submit(owner,mode,request.get('side'),files)
            submitted[request['id']]=job_id
        return {'job_id':job_id}
    if url.startswith('/api/quantification/'):
        job=manager.get(url.removeprefix('/api/quantification/'),owner)
        if not job:raise ValueError('Unknown or expired job.')
        result={'status':job['state']}
        if job['state']=='error':result['error']=job['error']
        if job['state']=='complete':result['result']=job['result']
        return result
    if url.startswith('/api/registration/'):
        key=url.removeprefix('/api/registration/')
        job=manager.get(key,owner)
        if not job:raise ValueError('Unknown or expired job.')
        result={'status':job['state'], 'elapsed_seconds':time.time()-job.get('started',job['created']), 'stage':job.get('stage','Queued')}
        if job['state']=='error':result['error']=job['error']
        if job['state']=='complete':
            result['result']=job['result']
            for field,name,mime in [('qc_url','qc.png','image/png'),('mask_url','Core_MNI.nii.gz','application/gzip')]:
                result[field]='data:'+mime+';base64,'+base64.b64encode((job['folder']/name).read_bytes()).decode()
        return result
    raise ValueError('Unknown request.')

PAYLOAD = ''
component=components.declare_component('coremap_original',path=frontend())
manager=service()
if 'original_owner' not in st.session_state:st.session_state.original_owner=uuid.uuid4().hex
def receive_request():
    request=st.session_state.get('original_coremap')
    if not isinstance(request,dict) or not request.get('id'):
        return
    cache=st.session_state.setdefault('original_responses',{})
    request_id=request['id']
    if request_id not in cache:
        try:
            print('CoreMap handling',request['url'],flush=True)
            data=handle(request,service(),st.session_state.original_owner);code=200
        except Exception as error:
            data={'error':str(error)};code=400
        cache[request_id]={'id':request_id,'code':code,'data':data}
        while len(cache)>32:
            del cache[next(iter(cache))]
    st.session_state.original_response=cache[request_id]
    print('CoreMap response ready',request['url'],cache[request_id]['code'],flush=True)

component(build=BUILD,response=st.session_state.get('original_response'),key='original_coremap',
          default=None,on_change=receive_request)
